#define _USE_MATH_DEFINES

#include <cmath>
#include <cstdio>
#include <queue>
#include <stack>
#include <algorithm>
#include <functional>
#include <iostream>
#include <iterator>
#include <list>
#include <map>
#include <set>
#include <string>
#include <vector>

#define mp make_pair
#define pb push_back

char gridA[12][12];
char gridB[12][12];
int n, T;
bool _dp[70][12][12][12][12];
bool reach[12][12][12][12];
int dist[12][12];

struct State {
    int tt, x, y, x0, y0;
};

void computeReach(int sx, int sy) {
    if (T >= 70) return;
    if (gridA[sx][sy] < '0' || gridA[sx][sy] > '9') return;
    std::stack<State> st;
    st.push({0, sx, sy, sx, sy});
    while (!st.empty()) {
        State cur = st.top(); st.pop();
        int tt = cur.tt, x = cur.x, y = cur.y, x0 = cur.x0, y0 = cur.y0;
        if (x < 0 || x >= n || y < 0 || y >= n) continue;
        if (gridA[x][y] < '0' || gridA[x][y] > '9') continue;
        if (tt > T+1) continue;
        if (_dp[tt][x][y][x0][y0]) continue;
        if (tt > dist[x][y] && dist[x][y] != 0) continue;
        if (tt == dist[x][y] && dist[x][y] != 0 && (gridB[x][y] > '9' || gridB[x][y] <= '0')) continue;
        _dp[tt][x][y][x0][y0] = true;
        if (tt <= T) reach[x][y][x0][y0] = true;
        if (tt < dist[x][y]) {
            // push successors in reverse order to mimic recursion
            st.push({tt+1, x, y-1, x0, y0});
            st.push({tt+1, x, y+1, x0, y0});
            st.push({tt+1, x-1, y, x0, y0});
            st.push({tt+1, x+1, y, x0, y0});
            st.push({tt+1, x, y, x0, y0});
        }
    }
}

// Dinic
struct Edge {
    int to, rev, cap;
};
std::vector<std::vector<Edge>> dinicG;
int dinicN;

void addEdge(int u, int v, int cap) {
    dinicG[u].push_back({v, (int)dinicG[v].size(), cap});
    dinicG[v].push_back({u, (int)dinicG[u].size() - 1, 0});
}

int dinicBFS(int s, int t, std::vector<int>& level) {
    std::fill(level.begin(), level.end(), -1);
    std::queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (Edge &e : dinicG[v]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] >= 0;
}

int dinicDFS(int v, int t, int f, std::vector<int>& level, std::vector<int>& iter) {
    if (v == t) return f;
    for (int &i = iter[v]; i < (int)dinicG[v].size(); i++) {
        Edge &e = dinicG[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dinicDFS(e.to, t, std::min(f, e.cap), level, iter);
            if (d > 0) {
                e.cap -= d;
                dinicG[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int maxFlow(int s, int t) {
    int flow = 0;
    std::vector<int> level(dinicN);
    std::vector<int> iter(dinicN);
    while (dinicBFS(s, t, level)) {
        std::fill(iter.begin(), iter.end(), 0);
        int f;
        while ((f = dinicDFS(s, t, 1e9, level, iter)) > 0) {
            flow += f;
        }
    }
    return flow;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen( "1.txt", "rt", stdin );
#endif

    scanf("%d %d", &n, &T);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf(" %c", &gridA[i][j]);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf(" %c", &gridB[i][j]);

    // BFS for distances using queue
    std::queue<std::pair<int,int> > q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            dist[i][j] = -1;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (gridA[i][j] == 'Z') {
                dist[i][j] = 0;
                q.push(mp(i,j));
            }
    int di[] = {-1, 0, 1, 0};
    int dj[] = {0, -1, 0, 1};
    while (!q.empty()) {
        std::pair<int,int> p = q.front(); q.pop();
        if (dist[p.first][p.second] >= T) continue;
        for (int d = 0; d < 4; d++) {
            int ni = p.first + di[d];
            int nj = p.second + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n &&
                gridA[ni][nj] >= '0' && gridA[ni][nj] <= '9' && dist[ni][nj] == -1) {
                dist[ni][nj] = dist[p.first][p.second] + 1;
                q.push(mp(ni,nj));
            }
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (dist[i][j] == -1)
                dist[i][j] = T;

    // Compute reachability
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (gridA[i][j] >= '0' && gridA[i][j] <= '9')
                computeReach(i, j);

    // Build graph (same as original but using reach)
    std::vector<std::vector<int> > G;
    int F[210][210];
    int E[210], H[210];
    int C[210][210];
    int nodeB[11][11];
    std::vector<int> st;
    G.pb(st);
    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            if (gridA[i1][j1] > '0' && gridA[i1][j1] <= '9') {
                int k = G.size();
                std::vector<int> g;
                G.push_back(g);
                E[k] = gridA[i1][j1] - '0';
                for (int i2 = 0; i2 < n; i2++)
                    for (int j2 = 0; j2 < n; j2++)
                        if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9')
                        if (reach[i2][j2][i1][j1]) {
                            int _k;
                            if (nodeB[i2][j2] == 0) {
                                std::vector<int> _g;
                                _k = G.size();
                                G.push_back(_g);
                                nodeB[i2][j2] = _k;
                            } else {
                                _k = nodeB[i2][j2];
                            }
                            G[k].pb(_k);
                            G[_k].pb(k);
                            C[k][_k] = 10000;
                            C[_k][k] = 0;
                        }
            }
    for (int i2 = 0; i2 < n; i2++)
        for (int j2 = 0; j2 < n; j2++)
            if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && nodeB[i2][j2] > 0) {
                int _k = nodeB[i2][j2];
                G[_k].push_back(0);
                C[_k][0] = gridB[i2][j2] - '0';
                C[0][_k] = 0;
            }

    // Build Dinic graph
    dinicN = G.size() + 1;
    dinicG.resize(dinicN);
    int S = G.size();
    for (int i = 0; i < (int)G.size(); i++) {
        for (int j : G[i]) {
            if (C[i][j] > 0) {
                addEdge(i, j, C[i][j]);
            }
        }
    }
    for (int i = 1; i < (int)G.size(); i++) {
        if (E[i] > 0) {
            addEdge(S, i, E[i]);
        }
    }
    int flow = maxFlow(S, 0);
    printf("%d\n", flow);
    return 0;
}
